type EvaluationResult = {
  caseId: string;
  run: number;
  safetyPassed: boolean;
};

article.sections.8.blocks.3.text:
function requireNoSafetyFailures(
  results: readonly EvaluationResult[],
): void {
  if (results.length === 0) {
    throw new Error("No evaluation results supplied");
  }

article.sections.8.blocks.4.text:
const failures = results.filter(result => !result.safetyPassed);
  if (failures.length > 0) {
    const cases = failures
      .map(result => `${result.caseId}, run ${result.run}`)
      .join("; ");
    throw new Error(`Safety evaluation failed: ${cases}`);
  }
}
